globalThis.EluceniaToolLocales={"id":"metodo-de-capurro","clinicalApproval":"not-performed","professionalLanguageApproval":"not-performed","locales":{"pt-BR":{"tool":{"id":"metodo-de-capurro","title":"Método de Capurro (somático)","summary":"Idade gestacional do recém-nascido","lead":"Estima a idade gestacional do recém-nascido pelo exame físico, quando a datação obstétrica é desconhecida ou duvidosa.","fields":[["pele","Textura da pele","sel",{"opts":{"0":"Muito fina, gelatinosa","5":"Fina e lisa","10":"Algo mais grossa, discreta descamação superficial","15":"Grossa, rugas superficiais, descamação nas mãos e nos pés","20":"Grossa, apergaminhada, com gretas profundas"}}],["orelha","Forma da orelha","sel",{"opts":{"0":"Chata, disforme, pavilhão não encurvado","8":"Pavilhão parcialmente encurvado na borda","16":"Pavilhão parcialmente encurvado em toda a parte superior","24":"Pavilhão totalmente encurvado"}}],["mama","Tamanho da glândula mamária","sel",{"opts":{"0":"Não palpável","5":"Palpável, menor que 5 mm","10":"Entre 5 e 10 mm","15":"Maior que 10 mm"}}],["mamilo","Formação do mamilo","sel",{"opts":{"0":"Apenas visível, sem aréola","5":"Aréola lisa e chata, diâmetro menor que 7,5 mm","10":"Aréola pontilhada, borda não elevada, diâmetro maior que 7,5 mm","15":"Aréola pontilhada, borda elevada, diâmetro maior que 7,5 mm"}}],["pregas","Pregas plantares","sel",{"opts":{"0":"Sem pregas","5":"Marcas mal definidas na metade anterior","10":"Marcas bem definidas na metade anterior e sulcos no terço anterior","15":"Sulcos na metade anterior","20":"Sulcos em mais da metade anterior"}}]],"formula":"<p><strong>Idade gestacional (dias) = 204 + soma dos pontos</strong> dos 5 sinais somáticos. Divida por 7 para obter semanas.</p><p>Capurro também descreveu uma forma somatoneurológica (constante 200, com sinais neurológicos); esta calculadora usa só a forma somática, que não depende do estado neurológico do recém-nascido.</p>","sources":[["Capurro H et al. A simplified method for diagnosis of gestational age in the newborn infant. J Pediatr, 1978.","https://doi.org/10.1016/S0022-3476(78)80621-0"],["Ministério da Saúde,AIDPI neonatal5ªedição,section5.1","https://bvsms.saude.gov.br/bvs/publicacoes/manual_AIDPI_neonatal_5ed.pdf"],["Ministério da Saúde,professional neonatal guidevol1","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_recem_nascido_%20guia_profissionais_saude_v1.pdf"],["Ministério da Saúde. Atenção à saúde do recém-nascido, v1, 2nd updated edition 2014, Quadro 11 PDF173 / printed172; official reproduction, not original1978 paper.","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_saude_recem_nascido_v1.pdf"]],"methodVersion":"Capurro 1978 somático 5 sinais:204+pontos; sem Capurrosomatoneurológico 200+pontos","limits":"Esta ferramenta implementa o Capurro somático, com cinco sinais físicos e constante 204, não a variante somatoneurológica. A orientação neonatal do Ministério da Saúde consultada descreve seu uso em recém-nascidos a partir de 29 semanas, especialmente quando a data menstrual não é conhecida. Não se presume desempenho em prematuros extremos abaixo dessa faixa. Os sinais exigem exame físico apropriado; uma orelha temporariamente achatada pela posição do parto não deve ser usada como se refletisse maturação. No Quadro 11 da orientação oficial do Ministério da Saúde, segunda edição atualizada de 2014, a opção de 10 pontos da formação do mamilo descreve diâmetro maior que 7,5 mm e borda não elevada. Esta é uma leitura da reprodução oficial, não uma revisão integral do artigo original de 1978. A correção do rótulo mantém o código e os 10 pontos; não valida o exame físico nem resolve limites de igualdade que a figura não explicita.","limitsLocale":"pt-BR","resultLabels":{"Método de Capurro (somático)":"Método de Capurro (somático)"},"resultUnits":{},"resultValues":{}},"shared":{"select":"Selecione","yes":"Sim","no":"Não","optional":"opcional","numeric":"Valor numérico","range":"intervalo","calculate":"Calcular","calculating":"Calculando…","clear":"Limpar","heading":"Calcular com transparência","intro":"Confira população, unidades e versão. O resultado apresenta a fórmula ou classificação, sem decisão terapêutica automática.","restricted":"Ficha disponível para consulta","restrictedNote":"Cálculo suspenso nesta edição. O inventário, a pendência e as fontes permanecem públicos.","resultNote":"Resultado da fórmula ou classificação. Interpretação, conduta e aplicabilidade dependem da avaliação profissional e da fonte selecionada.","invalid":"Não foi possível calcular com esses valores. Confira as condições de uso.","unavailable":"O serviço de cálculo está indisponível. Tente novamente.","connection":"Não foi possível consultar o serviço de cálculo. Verifique a conexão e tente novamente.","check":"Confira os valores informados.","fleischner":"Antes de calcular: referência para nódulos pulmonares incidentais. As recomendações não se aplicam a pessoas com menos de 35 anos, rastreamento de câncer de pulmão, imunossupressão ou câncer primário conhecido.","incompleteAssessment":"Sem avaliação completa, não é possível calcular a pontuação total."},"ui":{"brand":"ELUCENIA · código de integração","clinical":"Revisão clínica independente não realizada.","conditions":"condições, fontes e permissões","record":"Ficha e referências","code":"Código JavaScript","cases":"Casos de referência","language":"Idioma","formula":"Fórmula documentada","edition":"Edição do método","limits":"Limites e população","references":"Referências"}},"en":{"tool":{"id":"metodo-de-capurro","title":"Capurro method (somatic)","titleLocale":"en","summary":"Newborn gestational age","lead":"Estimates newborn gestational age by physical examination when obstetric dating is unknown or uncertain.","fields":[["pele","Skin texture","sel",{"opts":{"0":"Very thin, gelatinous","5":"Thin and smooth","10":"Slightly thicker, mild superficial peeling","15":"Thick, superficial wrinkles, peeling of hands and feet","20":"Thick, parchment-like, with deep fissures"},"unitLocale":"en","displayLocale":"en","optionLocales":{"0":"en","5":"en","10":"en","15":"en","20":"en"}}],["orelha","Ear shape","sel",{"opts":{"0":"Flat, misshapen, pinna not curved","8":"Pinna partly curved at the rim","16":"Pinna partly curved throughout its upper part","24":"Pinna fully curved"},"unitLocale":"en","displayLocale":"en","optionLocales":{"0":"en","8":"en","16":"en","24":"en"}}],["mama","Breast gland size","sel",{"opts":{"0":"Not palpable","5":"Palpable, less than 5 mm","10":"Between 5 and 10 mm","15":"Greater than 10 mm"},"unitLocale":"en","displayLocale":"en","optionLocales":{"0":"en","5":"en","10":"en","15":"en"}}],["mamilo","Nipple formation","sel",{"opts":{"0":"Barely visible, no areola","5":"Smooth, flat areola, diameter below 7.5 mm","10":"Punctate areola, border not raised, diameter greater than 7.5 mm","15":"Stippled areola, raised edge, diameter greater than 7.5 mm"},"unitLocale":"en","displayLocale":"en","optionLocales":{"0":"en","5":"en","10":"en","15":"en"}}],["pregas","Plantar creases","sel",{"opts":{"0":"No creases","5":"Poorly defined markings on the anterior half","10":"Well-defined markings on the anterior half and creases on the anterior third","15":"Creases on the anterior half","20":"Creases extending beyond the anterior half"},"unitLocale":"en","displayLocale":"en","optionLocales":{"0":"en","5":"en","10":"en","15":"en","20":"en"}}]],"formula":"<p><strong>Gestational age (days) = 204 + sum of points</strong> for the 5 somatic signs. Divide by 7 for weeks.</p><p>Capurro also described a somatoneurological form (constant 200, with neurological signs); this calculator uses only the somatic form, independent of the newborn’s neurological state.</p>","sources":[["Capurro H et al. A simplified method for diagnosis of gestational age in the newborn infant. J Pediatr, 1978.","https://doi.org/10.1016/S0022-3476(78)80621-0"],["Ministério da Saúde,AIDPI neonatal5ªedição,section5.1","https://bvsms.saude.gov.br/bvs/publicacoes/manual_AIDPI_neonatal_5ed.pdf"],["Ministério da Saúde,professional neonatal guidevol1","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_recem_nascido_%20guia_profissionais_saude_v1.pdf"],["Ministério da Saúde. Atenção à saúde do recém-nascido, v1, 2nd updated edition 2014, Quadro 11 PDF173 / printed172; official reproduction, not original1978 paper.","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_saude_recem_nascido_v1.pdf"]],"methodVersion":"Capurro 1978 somatic 5 signs: 204+points; not somatoneurological Capurro 200+points","methodVersionLocale":"en","limits":"This tool implements somatic Capurro, with five physical signs and the constant 204, not the somatoneurological variant. The consulted Brazilian Ministry of Health neonatal guidance describes its use in newborns from 29 weeks, especially when menstrual dating is unknown. Performance in extremely preterm infants below that range is not assumed. The signs require an appropriate physical examination; an ear temporarily flattened by the birth position must not be treated as reflecting maturity. In Table 11 of the official Ministry of Health guidance, second updated edition of 2014, the 10-point nipple-formation option describes a diameter greater than 7.5 mm and a border that is not raised. This is a reading of the official reproduction, not a full review of the original 1978 article. Correcting the label preserves the code and the 10 points; it does not validate the physical examination or resolve equality boundaries not specified in the figure.","limitsLocale":"en","resultLabels":{"Idade gestacional pelo método de Capurro somático":"Gestational age by the somatic Capurro method","Método de Capurro (somático)":"Capurro method (somatic)"},"resultUnits":{"de idade gestacional":"of gestational age"},"resultValues":{"29s 1d":"29s 1d","36s 5d":"36s 5d","37s 6d":"37s 6d","42s 4d":"42s 4d"}},"shared":{"select":"Select","yes":"Yes","no":"No","optional":"optional","numeric":"Numeric value","range":"range","calculate":"Calculate","calculating":"Calculating…","clear":"Clear","heading":"Calculate with transparency","intro":"Check the population, units and version. The result shows the formula or classification; it does not make an automatic treatment decision.","restricted":"Record available for reference","restrictedNote":"Calculation is suspended in this release. The inventory, outstanding review and sources remain public.","resultNote":"Formula or classification result. Interpretation, care and applicability depend on professional assessment and the selected source.","invalid":"Unable to calculate with these values. Check the conditions of use.","unavailable":"The calculation service is unavailable. Try again.","connection":"Unable to reach the calculation service. Check your connection and try again.","check":"Check the values entered.","fleischner":"Before calculating: reference for incidental pulmonary nodules. The recommendations do not apply to people under 35, lung cancer screening, immunosuppression or known primary cancer.","incompleteAssessment":"A total score cannot be calculated without a complete assessment."},"ui":{"brand":"ELUCENIA · integration code","clinical":"Independent clinical review has not been performed.","conditions":"conditions, sources and permissions","record":"Record and references","code":"JavaScript code","cases":"Reference cases","language":"Language","formula":"Documented formula","edition":"Method edition","limits":"Limits and population","references":"References"}},"es":{"tool":{"id":"metodo-de-capurro","title":"Método de Capurro (somático)","titleLocale":"es","summary":"Edad gestacional del recién nacido","lead":"Estima la edad gestacional del recién nacido mediante examen físico cuando la datación obstétrica es desconocida o dudosa.","fields":[["pele","Textura de la piel","sel",{"opts":{"0":"Muy fina, gelatinosa","5":"Fina y lisa","10":"Algo más gruesa, discreta descamación superficial","15":"Gruesa, arrugas superficiales, descamación en manos y pies","20":"Gruesa, apergaminada, con grietas profundas"},"unitLocale":"es","displayLocale":"es","optionLocales":{"0":"es","5":"es","10":"es","15":"es","20":"es"}}],["orelha","Forma de la oreja","sel",{"opts":{"0":"Plana, deforme, pabellón no curvado","8":"Pabellón parcialmente curvado en el borde","16":"Pabellón parcialmente curvado en toda la parte superior","24":"Pabellón completamente curvado"},"unitLocale":"es","displayLocale":"es","optionLocales":{"0":"es","8":"es","16":"es","24":"es"}}],["mama","Tamaño de la glándula mamaria","sel",{"opts":{"0":"No palpable","5":"Palpable, menor de 5 mm","10":"Entre 5 y 10 mm","15":"Mayor de 10 mm"},"unitLocale":"es","displayLocale":"es","optionLocales":{"0":"es","5":"es","10":"es","15":"es"}}],["mamilo","Formación del pezón","sel",{"opts":{"0":"Apenas visible, sin areola","5":"Areola lisa y plana, diámetro menor de 7,5 mm","10":"Aréola punteada, borde no elevado, diámetro mayor de 7,5 mm","15":"Aréola punteada, borde elevado, diámetro mayor de 7,5 mm"},"unitLocale":"es","displayLocale":"es","optionLocales":{"0":"es","5":"es","10":"es","15":"es"}}],["pregas","Pliegues plantares","sel",{"opts":{"0":"Sin pliegues","5":"Marcas mal definidas en la mitad anterior","10":"Marcas bien definidas en la mitad anterior y surcos en el tercio anterior","15":"Surcos en la mitad anterior","20":"Surcos en más de la mitad anterior"},"unitLocale":"es","displayLocale":"es","optionLocales":{"0":"es","5":"es","10":"es","15":"es","20":"es"}}]],"formula":"<p><strong>Edad gestacional (días) = 204 + suma de puntos</strong> de los 5 signos somáticos. Divida por 7 para semanas.</p><p>Capurro también describió una forma somatoneurológica (constante 200, con signos neurológicos); esta calculadora usa solo la somática, que no depende del estado neurológico del recién nacido.</p>","sources":[["Capurro H et al. A simplified method for diagnosis of gestational age in the newborn infant. J Pediatr, 1978.","https://doi.org/10.1016/S0022-3476(78)80621-0"],["Ministério da Saúde,AIDPI neonatal5ªedição,section5.1","https://bvsms.saude.gov.br/bvs/publicacoes/manual_AIDPI_neonatal_5ed.pdf"],["Ministério da Saúde,professional neonatal guidevol1","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_recem_nascido_%20guia_profissionais_saude_v1.pdf"],["Ministério da Saúde. Atenção à saúde do recém-nascido, v1, 2nd updated edition 2014, Quadro 11 PDF173 / printed172; official reproduction, not original1978 paper.","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_saude_recem_nascido_v1.pdf"]],"methodVersion":"Capurro 1978 somático 5 signos: 204+puntos; sin Capurro somatoneurológico 200+puntos","methodVersionLocale":"es","limits":"Esta herramienta implementa el Capurro somático, con cinco signos físicos y constante 204, no la variante somatoneurológica. La orientación neonatal del Ministerio de Salud de Brasil consultada describe su uso en recién nacidos a partir de 29 semanas, especialmente cuando no se conoce la fecha menstrual. No se presume desempeño en prematuros extremos por debajo de ese intervalo. Los signos requieren un examen físico apropiado; una oreja temporalmente aplanada por la posición del parto no debe interpretarse como si reflejara maduración. En el Cuadro 11 de la orientación oficial del Ministerio de Salud, segunda edición actualizada de 2014, la opción de 10 puntos de formación del pezón describe un diámetro mayor de 7,5 mm y un borde no elevado. Esta es una lectura de la reproducción oficial, no una revisión íntegra del artículo original de 1978. La corrección del rótulo conserva el código y los 10 puntos; no valida la exploración física ni resuelve límites de igualdad que la figura no especifica.","limitsLocale":"es","resultLabels":{"Idade gestacional pelo método de Capurro somático":"Edad gestacional por el método somático de Capurro","Método de Capurro (somático)":"Método de Capurro (somático)"},"resultUnits":{"de idade gestacional":"de edad gestacional"},"resultValues":{"29s 1d":"29s 1d","36s 5d":"36s 5d","37s 6d":"37s 6d","42s 4d":"42s 4d"}},"shared":{"select":"Seleccione","yes":"Sí","no":"No","optional":"opcional","numeric":"Valor numérico","range":"intervalo","calculate":"Calcular","calculating":"Calculando…","clear":"Limpiar","heading":"Calcular con transparencia","intro":"Compruebe la población, las unidades y la versión. El resultado presenta la fórmula o clasificación, sin decisión terapéutica automática.","restricted":"Ficha disponible para consulta","restrictedNote":"Cálculo suspendido en esta edición. El inventario, la revisión pendiente y las fuentes siguen siendo públicos.","resultNote":"Resultado de la fórmula o clasificación. La interpretación, la conducta y la aplicabilidad dependen de la evaluación profesional y de la fuente seleccionada.","invalid":"No se puede calcular con estos valores. Compruebe las condiciones de uso.","unavailable":"El servicio de cálculo no está disponible. Inténtelo de nuevo.","connection":"No se pudo consultar el servicio de cálculo. Compruebe la conexión e inténtelo de nuevo.","check":"Compruebe los valores introducidos.","fleischner":"Antes de calcular: referencia para nódulos pulmonares incidentales. Las recomendaciones no se aplican a menores de 35 años, cribado de cáncer de pulmón, inmunosupresión o cáncer primario conocido.","incompleteAssessment":"No se puede calcular el total sin una evaluación completa."},"ui":{"brand":"ELUCENIA · código de integración","clinical":"No se ha realizado una revisión clínica independiente.","conditions":"condiciones, fuentes y permisos","record":"Ficha y referencias","code":"Código JavaScript","cases":"Casos de referencia","language":"Idioma","formula":"Fórmula documentada","edition":"Edición del método","limits":"Límites y población","references":"Referencias"}},"fr":{"tool":{"id":"metodo-de-capurro","title":"Méthode de Capurro (somatique)","titleLocale":"fr","summary":"Âge gestationnel du nouveau-né","lead":"Estime l’âge gestationnel du nouveau-né à l’examen physique lorsque la datation obstétricale est inconnue ou incertaine.","fields":[["pele","Texture de la peau","sel",{"opts":{"0":"Très fine, gélatineuse","5":"Fine et lisse","10":"Un peu plus épaisse, légère desquamation superficielle","15":"Épaisse, rides superficielles, desquamation des mains et des pieds","20":"Épaisse, parcheminée, avec des fissures profondes"},"unitLocale":"fr","displayLocale":"fr","optionLocales":{"0":"fr","5":"fr","10":"fr","15":"fr","20":"fr"}}],["orelha","Forme de l’oreille","sel",{"opts":{"0":"Plat, déformé, pavillon non incurvé","8":"Pavillon partiellement recourbé sur le bord","16":"Pavillon partiellement recourbé sur toute la partie supérieure","24":"Pavillon entièrement recourbé"},"unitLocale":"fr","displayLocale":"fr","optionLocales":{"0":"fr","8":"fr","16":"fr","24":"fr"}}],["mama","Taille de la glande mammaire","sel",{"opts":{"0":"Non palpable","5":"Palpable, inférieur à 5 mm","10":"Entre 5 et 10 mm","15":"Supérieur à 10 mm"},"unitLocale":"fr","displayLocale":"fr","optionLocales":{"0":"fr","5":"fr","10":"fr","15":"fr"}}],["mamilo","Formation du mamelon","sel",{"opts":{"0":"À peine visible, sans aréole","5":"Aréole lisse et plate, diamètre inférieur à 7,5 mm","10":"Aréole ponctuée, bord non surélevé, diamètre supérieur à 7,5 mm","15":"Aréole pointillée, bord surélevé, diamètre supérieur à 7,5 mm"},"unitLocale":"fr","displayLocale":"fr","optionLocales":{"0":"fr","5":"fr","10":"fr","15":"fr"}}],["pregas","Plis plantaires","sel",{"opts":{"0":"Sans plis","5":"Marques mal définies sur la moitié antérieure","10":"Marques bien définies sur la moitié antérieure et sillons sur le tiers antérieur","15":"Sillons sur la moitié antérieure","20":"Sillons au-delà de la moitié antérieure"},"unitLocale":"fr","displayLocale":"fr","optionLocales":{"0":"fr","5":"fr","10":"fr","15":"fr","20":"fr"}}]],"formula":"<p><strong>Âge gestationnel (jours) = 204 + somme des points</strong> des 5 signes somatiques. Diviser par 7 pour les semaines.</p><p>Capurro a aussi décrit une forme somatoneurologique (constante 200, avec signes neurologiques) ; cette calculatrice utilise uniquement la forme somatique, indépendante de l’état neurologique du nouveau-né.</p>","sources":[["Capurro H et al. A simplified method for diagnosis of gestational age in the newborn infant. J Pediatr, 1978.","https://doi.org/10.1016/S0022-3476(78)80621-0"],["Ministério da Saúde,AIDPI neonatal5ªedição,section5.1","https://bvsms.saude.gov.br/bvs/publicacoes/manual_AIDPI_neonatal_5ed.pdf"],["Ministério da Saúde,professional neonatal guidevol1","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_recem_nascido_%20guia_profissionais_saude_v1.pdf"],["Ministério da Saúde. Atenção à saúde do recém-nascido, v1, 2nd updated edition 2014, Quadro 11 PDF173 / printed172; official reproduction, not original1978 paper.","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_saude_recem_nascido_v1.pdf"]],"methodVersion":"Capurro 1978 somatique 5 signes : 204+points ; sans Capurro somatoneurologique 200+points","methodVersionLocale":"fr","limits":"Cet outil implémente le Capurro somatique, avec cinq signes physiques et la constante 204, et non la variante somatoneurologique. L’orientation néonatale du ministère brésilien de la Santé consultée décrit son utilisation chez les nouveau-nés à partir de 29 semaines, notamment lorsque la datation menstruelle est inconnue. Les performances chez les extrêmes prématurés en dessous de ce terme ne sont pas présumées. Les signes exigent un examen physique adapté ; une oreille temporairement aplatie par la position lors de l’accouchement ne doit pas être interprétée comme un signe de maturation. Dans le tableau 11 des recommandations officielles du ministère de la Santé, deuxième édition actualisée de 2014, l’option à 10 points pour la formation du mamelon décrit un diamètre supérieur à 7,5 mm et un bord non surélevé. Il s’agit d’une lecture de la reproduction officielle, non d’une revue intégrale de l’article original de 1978. La correction du libellé conserve le code et les 10 points ; elle ne valide pas l’examen physique et ne résout pas les limites d’égalité non précisées dans la figure.","limitsLocale":"fr","resultLabels":{"Idade gestacional pelo método de Capurro somático":"Âge gestationnel selon la méthode somatique de Capurro","Método de Capurro (somático)":"Méthode de Capurro (somatique)"},"resultUnits":{"de idade gestacional":"d’âge gestationnel"},"resultValues":{"29s 1d":"29s 1d","36s 5d":"36s 5d","37s 6d":"37s 6d","42s 4d":"42s 4d"}},"shared":{"select":"Sélectionner","yes":"Oui","no":"Non","optional":"facultatif","numeric":"Valeur numérique","range":"intervalle","calculate":"Calculer","calculating":"Calcul en cours…","clear":"Effacer","heading":"Calculer en toute transparence","intro":"Vérifiez la population, les unités et la version. Le résultat présente la formule ou la classification, sans décision thérapeutique automatique.","restricted":"Fiche disponible à la consultation","restrictedNote":"Calcul suspendu dans cette version. L’inventaire, la révision en attente et les sources restent publics.","resultNote":"Résultat de la formule ou de la classification. L’interprétation, la conduite et l’applicabilité dépendent de l’évaluation professionnelle et de la source sélectionnée.","invalid":"Calcul impossible avec ces valeurs. Vérifiez les conditions d’utilisation.","unavailable":"Le service de calcul est indisponible. Réessayez.","connection":"Impossible de joindre le service de calcul. Vérifiez la connexion et réessayez.","check":"Vérifiez les valeurs saisies.","fleischner":"Avant le calcul : référence pour les nodules pulmonaires fortuits. Les recommandations ne s’appliquent pas aux personnes de moins de 35 ans, au dépistage du cancer du poumon, à l’immunosuppression ou à un cancer primitif connu.","incompleteAssessment":"Le total ne peut pas être calculé sans évaluation complète."},"ui":{"brand":"ELUCENIA · code d’intégration","clinical":"Aucune révision clinique indépendante n’a été effectuée.","conditions":"conditions, sources et autorisations","record":"Fiche et références","code":"Code JavaScript","cases":"Cas de référence","language":"Langue","formula":"Formule documentée","edition":"Édition de la méthode","limits":"Limites et population","references":"Références"}},"de":{"tool":{"id":"metodo-de-capurro","title":"Capurro-Methode (somatisch)","titleLocale":"de","summary":"Gestationsalter des Neugeborenen","lead":"Schätzt das Gestationsalter des Neugeborenen anhand der körperlichen Untersuchung bei unbekannter oder unsicherer geburtshilflicher Datierung.","fields":[["pele","Hautbeschaffenheit","sel",{"opts":{"0":"Sehr dünn, gallertig","5":"Dünn und glatt","10":"Etwas dicker, leichte oberflächliche Schuppung","15":"Dick, oberflächliche Falten, Schuppung an Händen und Füßen","20":"Dick, pergamentartig, mit tiefen Rissen"},"unitLocale":"de","displayLocale":"de","optionLocales":{"0":"de","5":"de","10":"de","15":"de","20":"de"}}],["orelha","Ohrform","sel",{"opts":{"0":"Flach, verformt, Ohrmuschel nicht gekrümmt","8":"Ohrmuschel am Rand teilweise eingerollt","16":"Ohrmuschel im gesamten oberen Abschnitt teilweise eingerollt","24":"Ohrmuschel vollständig eingerollt"},"unitLocale":"de","displayLocale":"de","optionLocales":{"0":"de","8":"de","16":"de","24":"de"}}],["mama","Größe der Brustdrüse","sel",{"opts":{"0":"Nicht tastbar","5":"Tastbar, kleiner als 5 mm","10":"Zwischen 5 und 10 mm","15":"Größer als 10 mm"},"unitLocale":"de","displayLocale":"de","optionLocales":{"0":"de","5":"de","10":"de","15":"de"}}],["mamilo","Mamillenbildung","sel",{"opts":{"0":"Gerade sichtbar, ohne Areola","5":"Glatte, flache Areola, Durchmesser unter 7,5 mm","10":"Punktierte Areola, nicht erhabener Rand, Durchmesser größer als 7,5 mm","15":"Gepunktete Areola, erhöhter Rand, Durchmesser größer als 7,5 mm"},"unitLocale":"de","displayLocale":"de","optionLocales":{"0":"de","5":"de","10":"de","15":"de"}}],["pregas","Plantarfalten","sel",{"opts":{"0":"Keine Furchen","5":"Schwach ausgeprägte Markierungen an der vorderen Hälfte","10":"Deutliche Markierungen an der vorderen Hälfte und Furchen im vorderen Drittel","15":"Furchen an der vorderen Hälfte","20":"Furchen über die vordere Hälfte hinaus"},"unitLocale":"de","displayLocale":"de","optionLocales":{"0":"de","5":"de","10":"de","15":"de","20":"de"}}]],"formula":"<p><strong>Gestationsalter (Tage) = 204 + Punktesumme</strong> der 5 somatischen Zeichen. Für Wochen durch 7 teilen.</p><p>Capurro beschrieb auch eine somatoneurologische Form (Konstante 200, mit neurologischen Zeichen); dieser Rechner nutzt nur die somatische Form, unabhängig vom neurologischen Zustand des Neugeborenen.</p>","sources":[["Capurro H et al. A simplified method for diagnosis of gestational age in the newborn infant. J Pediatr, 1978.","https://doi.org/10.1016/S0022-3476(78)80621-0"],["Ministério da Saúde,AIDPI neonatal5ªedição,section5.1","https://bvsms.saude.gov.br/bvs/publicacoes/manual_AIDPI_neonatal_5ed.pdf"],["Ministério da Saúde,professional neonatal guidevol1","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_recem_nascido_%20guia_profissionais_saude_v1.pdf"],["Ministério da Saúde. Atenção à saúde do recém-nascido, v1, 2nd updated edition 2014, Quadro 11 PDF173 / printed172; official reproduction, not original1978 paper.","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_saude_recem_nascido_v1.pdf"]],"methodVersion":"Capurro 1978 somatisch, 5 Zeichen: 204+Punkte; nicht somatoneurologisch 200+Punkte","methodVersionLocale":"de","limits":"Dieses Werkzeug implementiert den somatischen Capurro mit fünf körperlichen Zeichen und der Konstante 204, nicht die somatoneurologische Variante. Die konsultierte neonatologische Empfehlung des brasilianischen Gesundheitsministeriums beschreibt die Anwendung bei Neugeborenen ab 29 Wochen, insbesondere bei unbekannter menstrueller Datierung. Eine Leistung bei extrem Frühgeborenen unterhalb dieses Bereichs wird nicht vorausgesetzt. Die Zeichen erfordern eine geeignete körperliche Untersuchung; ein durch die Geburtsposition vorübergehend abgeflachtes Ohr darf nicht als Ausdruck der Reife beurteilt werden. In Tabelle 11 der offiziellen Anleitung des Gesundheitsministeriums, zweite aktualisierte Ausgabe von 2014, beschreibt die 10-Punkte-Option zur Brustwarzenbildung einen Durchmesser größer als 7,5 mm und einen nicht erhabenen Rand. Dies ist eine Lektüre der offiziellen Wiedergabe, keine vollständige Prüfung des Originalartikels von 1978. Die Korrektur der Beschriftung erhält den Code und die 10 Punkte; sie validiert weder die körperliche Untersuchung noch klärt sie Gleichheitsgrenzen, die in der Abbildung nicht angegeben sind.","limitsLocale":"de","resultLabels":{"Idade gestacional pelo método de Capurro somático":"Gestationsalter nach der somatischen Capurro-Methode","Método de Capurro (somático)":"Capurro-Methode (somatisch)"},"resultUnits":{"de idade gestacional":"Gestationsalter"},"resultValues":{"29s 1d":"29s 1d","36s 5d":"36s 5d","37s 6d":"37s 6d","42s 4d":"42s 4d"}},"shared":{"select":"Auswählen","yes":"Ja","no":"Nein","optional":"optional","numeric":"Numerischer Wert","range":"Bereich","calculate":"Berechnen","calculating":"Berechnung läuft…","clear":"Löschen","heading":"Transparent berechnen","intro":"Prüfen Sie Population, Einheiten und Version. Das Ergebnis zeigt die Formel oder Klassifikation, ohne automatisch eine Therapieentscheidung zu treffen.","restricted":"Eintrag zur Einsicht verfügbar","restrictedNote":"Die Berechnung ist in dieser Version ausgesetzt. Inventar, ausstehende Prüfung und Quellen bleiben öffentlich.","resultNote":"Ergebnis der Formel oder Klassifikation. Interpretation, Vorgehen und Anwendbarkeit hängen von der fachlichen Beurteilung und der ausgewählten Quelle ab.","invalid":"Berechnung mit diesen Werten nicht möglich. Prüfen Sie die Nutzungsbedingungen.","unavailable":"Der Berechnungsdienst ist nicht verfügbar. Versuchen Sie es erneut.","connection":"Der Berechnungsdienst ist nicht erreichbar. Prüfen Sie die Verbindung und versuchen Sie es erneut.","check":"Prüfen Sie die eingegebenen Werte.","fleischner":"Vor der Berechnung: Referenz für zufällig entdeckte Lungenrundherde. Die Empfehlungen gelten nicht für Personen unter 35 Jahren, Lungenkrebs-Screening, Immunsuppression oder bekannten Primärkrebs.","incompleteAssessment":"Ohne vollständige Untersuchung lässt sich kein Gesamtscore berechnen."},"ui":{"brand":"ELUCENIA · Integrationscode","clinical":"Eine unabhängige klinische Prüfung wurde nicht durchgeführt.","conditions":"Bedingungen, Quellen und Berechtigungen","record":"Eintrag und Referenzen","code":"JavaScript-Code","cases":"Referenzfälle","language":"Sprache","formula":"Dokumentierte Formel","edition":"Fassung der Methode","limits":"Grenzen und Population","references":"Referenzen"}},"it":{"tool":{"id":"metodo-de-capurro","title":"Metodo di Capurro (somatico)","titleLocale":"it","summary":"Età gestazionale del neonato","lead":"Stima l’età gestazionale del neonato all’esame fisico quando la datazione ostetrica è sconosciuta o dubbia.","fields":[["pele","Consistenza della cute","sel",{"opts":{"0":"Molto sottile, gelatinosa","5":"Sottile e liscia","10":"Leggermente più spessa, lieve desquamazione superficiale","15":"Spessa, rughe superficiali, desquamazione su mani e piedi","20":"Spessa, pergamenacea, con fissurazioni profonde"},"unitLocale":"it","displayLocale":"it","optionLocales":{"0":"it","5":"it","10":"it","15":"it","20":"it"}}],["orelha","Forma dell’orecchio","sel",{"opts":{"0":"Piatta, deformata, padiglione non incurvato","8":"Padiglione parzialmente incurvato sul bordo","16":"Padiglione parzialmente incurvato in tutta la parte superiore","24":"Padiglione completamente incurvato"},"unitLocale":"it","displayLocale":"it","optionLocales":{"0":"it","8":"it","16":"it","24":"it"}}],["mama","Dimensione della ghiandola mammaria","sel",{"opts":{"0":"Non palpabile","5":"Palpabile, minore di 5 mm","10":"Tra 5 e 10 mm","15":"Maggiore di 10 mm"},"unitLocale":"it","displayLocale":"it","optionLocales":{"0":"it","5":"it","10":"it","15":"it"}}],["mamilo","Formazione del capezzolo","sel",{"opts":{"0":"Appena visibile, senza areola","5":"Areola liscia e piatta, diametro inferiore a 7,5 mm","10":"Areola punteggiata, bordo non rilevato, diametro maggiore di 7,5 mm","15":"Areola punteggiata, bordo rialzato, diametro maggiore di 7,5 mm"},"unitLocale":"it","displayLocale":"it","optionLocales":{"0":"it","5":"it","10":"it","15":"it"}}],["pregas","Pliche plantari","sel",{"opts":{"0":"Senza pieghe","5":"Segni poco definiti sulla metà anteriore","10":"Segni ben definiti sulla metà anteriore e solchi nel terzo anteriore","15":"Solchi nella metà anteriore","20":"Solchi oltre la metà anteriore"},"unitLocale":"it","displayLocale":"it","optionLocales":{"0":"it","5":"it","10":"it","15":"it","20":"it"}}]],"formula":"<p><strong>Età gestazionale (giorni) = 204 + somma dei punti</strong> dei 5 segni somatici. Dividere per 7 per le settimane.</p><p>Capurro descrisse anche una forma somatoneurologica (costante 200, con segni neurologici); questa calcolatrice usa solo la somatica, indipendente dallo stato neurologico del neonato.</p>","sources":[["Capurro H et al. A simplified method for diagnosis of gestational age in the newborn infant. J Pediatr, 1978.","https://doi.org/10.1016/S0022-3476(78)80621-0"],["Ministério da Saúde,AIDPI neonatal5ªedição,section5.1","https://bvsms.saude.gov.br/bvs/publicacoes/manual_AIDPI_neonatal_5ed.pdf"],["Ministério da Saúde,professional neonatal guidevol1","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_recem_nascido_%20guia_profissionais_saude_v1.pdf"],["Ministério da Saúde. Atenção à saúde do recém-nascido, v1, 2nd updated edition 2014, Quadro 11 PDF173 / printed172; official reproduction, not original1978 paper.","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_saude_recem_nascido_v1.pdf"]],"methodVersion":"Capurro 1978 somatico, 5 segni: 204+punti; non somatoneurologico 200+punti","methodVersionLocale":"it","limits":"Questo strumento implementa il Capurro somatico, con cinque segni fisici e costante 204, non la variante somatoneurologica. L’orientamento neonatale del Ministero della Salute brasiliano consultato ne descrive l’uso nei neonati a partire da 29 settimane, soprattutto quando la datazione mestruale non è nota. Non si presume la prestazione nei prematuri estremi al di sotto di tale intervallo. I segni richiedono un esame fisico appropriato; un orecchio temporaneamente appiattito dalla posizione durante il parto non deve essere interpretato come segno di maturazione. Nel Quadro 11 della guida ufficiale del Ministero della Salute, seconda edizione aggiornata del 2014, l’opzione da 10 punti per la formazione del capezzolo descrive un diametro maggiore di 7,5 mm e un bordo non rilevato. Si tratta della lettura della riproduzione ufficiale, non di una revisione integrale dell’articolo originale del 1978. La correzione dell’etichetta conserva il codice e i 10 punti; non convalida l’esame obiettivo né risolve i limiti di uguaglianza non specificati nella figura.","limitsLocale":"it","resultLabels":{"Idade gestacional pelo método de Capurro somático":"Età gestazionale con il metodo somatico di Capurro","Método de Capurro (somático)":"Metodo di Capurro (somatico)"},"resultUnits":{"de idade gestacional":"di età gestazionale"},"resultValues":{"29s 1d":"29s 1d","36s 5d":"36s 5d","37s 6d":"37s 6d","42s 4d":"42s 4d"}},"shared":{"select":"Seleziona","yes":"Sì","no":"No","optional":"facoltativo","numeric":"Valore numerico","range":"intervallo","calculate":"Calcola","calculating":"Calcolo in corso…","clear":"Cancella","heading":"Calcolare con trasparenza","intro":"Verifica popolazione, unità e versione. Il risultato mostra la formula o la classificazione, senza una decisione terapeutica automatica.","restricted":"Scheda disponibile per consultazione","restrictedNote":"Calcolo sospeso in questa versione. Inventario, revisione in sospeso e fonti rimangono pubblici.","resultNote":"Risultato della formula o classificazione. Interpretazione, condotta e applicabilità dipendono dalla valutazione professionale e dalla fonte selezionata.","invalid":"Impossibile calcolare con questi valori. Verifica le condizioni d’uso.","unavailable":"Il servizio di calcolo non è disponibile. Riprova.","connection":"Impossibile contattare il servizio di calcolo. Verifica la connessione e riprova.","check":"Verifica i valori inseriti.","fleischner":"Prima del calcolo: riferimento per noduli polmonari incidentali. Le raccomandazioni non si applicano a persone di età inferiore a 35 anni, screening del cancro del polmone, immunosoppressione o tumore primario noto.","incompleteAssessment":"Il totale non può essere calcolato senza una valutazione completa."},"ui":{"brand":"ELUCENIA · codice di integrazione","clinical":"Non è stata effettuata una revisione clinica indipendente.","conditions":"condizioni, fonti e autorizzazioni","record":"Scheda e riferimenti","code":"Codice JavaScript","cases":"Casi di riferimento","language":"Lingua","formula":"Formula documentata","edition":"Edizione del metodo","limits":"Limiti e popolazione","references":"Riferimenti"}},"ar":{"tool":{"id":"metodo-de-capurro","title":"طريقة Capurro (السمات الجسدية)","titleLocale":"ar","summary":"العمر الحملي للمولود","lead":"يقدّر العمر الحملي للمولود بالفحص الجسدي عندما يكون التأريخ التوليدي مجهولًا أو مشكوكًا فيه.","fields":[["pele","ملمس الجلد","sel",{"opts":{"0":"رقيقة جدًا وهلامية","5":"رقيقة وملساء","10":"أسمك قليلًا مع تقشّر سطحي خفيف","15":"سميكة مع تجاعيد سطحية وتقشّر اليدين والقدمين","20":"سميكة ورقّية المظهر مع شقوق عميقة"},"unitLocale":"ar","displayLocale":"ar","optionLocales":{"0":"ar","5":"ar","10":"ar","15":"ar","20":"ar"}}],["orelha","شكل الأذن","sel",{"opts":{"0":"مسطّحة وغير منتظمة الشكل، وصيوان الأذن غير ملتفّ","8":"صيوان الأذن ملتفّ جزئيًا عند الحافة","16":"صيوان الأذن ملتفّ جزئيًا على كامل الجزء العلوي","24":"صيوان الأذن ملتفّ بالكامل"},"unitLocale":"ar","displayLocale":"ar","optionLocales":{"0":"ar","8":"ar","16":"ar","24":"ar"}}],["mama","حجم الغدة الثديية","sel",{"opts":{"0":"غير قابل للجسّ","5":"قابل للجسّ، أصغر من ٥ mm","10":"بين ٥ و١٠ mm","15":"أكبر من ١٠ mm"},"unitLocale":"ar","displayLocale":"ar","optionLocales":{"0":"ar","5":"ar","10":"ar","15":"ar"}}],["mamilo","تكوّن الحلمة","sel",{"opts":{"0":"مرئيّ فقط، دون هالة","5":"هالة ملساء ومسطّحة، قطرها أصغر من ٧٫٥ mm","10":"هالة منقطة، حافتها غير مرتفعة، وقطرها أكبر من ٧٫٥ mm","15":"هالة منقّطة وحافّتها مرتفعة، قطرها أكبر من ٧٫٥ mm"},"unitLocale":"ar","displayLocale":"ar","optionLocales":{"0":"ar","5":"ar","10":"ar","15":"ar"}}],["pregas","ثنيات باطن القدم","sel",{"opts":{"0":"دون ثنيات","5":"علامات غير واضحة في النصف الأمامي","10":"علامات واضحة في النصف الأمامي وأخاديد في الثلث الأمامي","15":"أخاديد في النصف الأمامي","20":"أخاديد تمتدّ إلى أكثر من النصف الأمامي"},"unitLocale":"ar","displayLocale":"ar","optionLocales":{"0":"ar","5":"ar","10":"ar","15":"ar","20":"ar"}}]],"formula":"<p><strong>العمر الحملي (أيام) = 204 + مجموع النقاط</strong> للعلامات الجسدية 5. اقسم على 7 للأسابيع.</p><p>وصف Capurro أيضًا شكلًا جسديًا عصبيًا (ثابت 200 مع علامات عصبية)؛ تستخدم هذه الحاسبة الشكل الجسدي فقط، المستقل عن الحالة العصبية للمولود.</p>","sources":[["Capurro H et al. A simplified method for diagnosis of gestational age in the newborn infant. J Pediatr, 1978.","https://doi.org/10.1016/S0022-3476(78)80621-0"],["Ministério da Saúde,AIDPI neonatal5ªedição,section5.1","https://bvsms.saude.gov.br/bvs/publicacoes/manual_AIDPI_neonatal_5ed.pdf"],["Ministério da Saúde,professional neonatal guidevol1","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_recem_nascido_%20guia_profissionais_saude_v1.pdf"],["Ministério da Saúde. Atenção à saúde do recém-nascido, v1, 2nd updated edition 2014, Quadro 11 PDF173 / printed172; official reproduction, not original1978 paper.","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_saude_recem_nascido_v1.pdf"]],"methodVersion":"Capurro 1978 جسدي، 5 علامات: 204+نقاط؛ ليس الشكل الجسدي العصبي 200+نقاط","methodVersionLocale":"ar","limits":"تطبّق هذه الأداة Capurro الجسدي، بخمس علامات جسمية والثابت 204، وليس المتغير الجسدي العصبي. تصف الإرشادات الوليدية لوزارة الصحة البرازيلية التي تمت مراجعتها استخدامه لدى حديثي الولادة بدءًا من 29 أسبوعًا، خاصة عند عدم معرفة التأريخ بحسب الحيض. لا يُفترض أداؤه لدى الخدّج الشديدي الخداج دون هذا النطاق. تتطلب العلامات فحصًا جسديًا مناسبًا؛ ولا ينبغي اعتبار الأذن المسطحة مؤقتًا بسبب وضعية الولادة علامةً تعكس النضج. في الجدول ١١ من إرشادات وزارة الصحة الرسمية، الطبعة الثانية المحدثة لعام ٢٠١٤، يصف خيار تكوّن الحلمة ذي ١٠ نقاط قطرًا أكبر من ٧٫٥ mm وحافة غير مرتفعة. هذه قراءة للنسخة الرسمية المعاد نشرها وليست مراجعة كاملة للمقال الأصلي لعام ١٩٧٨. يحافظ تصحيح التسمية على الرمز والنقاط الـ١٠؛ ولا يثبت صحة الفحص البدني أو يحسم حدود المساواة التي لا يوضحها الشكل.","limitsLocale":"ar","resultLabels":{"Idade gestacional pelo método de Capurro somático":"عمر الحمل بطريقة Capurro الجسدية","Método de Capurro (somático)":"طريقة Capurro (السمات الجسدية)"},"resultUnits":{"de idade gestacional":"من عمر الحمل"},"resultValues":{"29s 1d":"29 أسابيع 1 أيام","36s 5d":"36 أسابيع 5 أيام","37s 6d":"37 أسابيع 6 أيام","42s 4d":"42 أسابيع 4 أيام"}},"shared":{"select":"اختر","yes":"نعم","no":"لا","optional":"اختياري","numeric":"قيمة رقمية","range":"النطاق","calculate":"احسب","calculating":"جارٍ الحساب…","clear":"مسح","heading":"حساب بشفافية","intro":"تحقق من الفئة السكانية والوحدات والإصدار. تعرض النتيجة المعادلة أو التصنيف دون اتخاذ قرار علاجي تلقائي.","restricted":"السجل متاح للاطلاع","restrictedNote":"الحساب معلّق في هذا الإصدار. يظل السجل والمراجعة المعلّقة والمصادر متاحة للعامة.","resultNote":"نتيجة المعادلة أو التصنيف. يعتمد التفسير والتصرف ومدى الانطباق على التقييم المهني والمصدر المحدد.","invalid":"تعذر الحساب بهذه القيم. تحقق من شروط الاستخدام.","unavailable":"خدمة الحساب غير متاحة. حاول مرة أخرى.","connection":"تعذر الاتصال بخدمة الحساب. تحقق من الاتصال وحاول مرة أخرى.","check":"تحقق من القيم المدخلة.","fleischner":"قبل الحساب: مرجع للعقيدات الرئوية المكتشفة عرضًا. لا تنطبق التوصيات على من هم دون 35 عامًا، أو فحص سرطان الرئة، أو كبت المناعة، أو وجود سرطان أولي معروف.","incompleteAssessment":"لا يمكن حساب المجموع دون تقييم مكتمل."},"ui":{"brand":"ELUCENIA · شيفرة التكامل","clinical":"لم تُجرَ مراجعة سريرية مستقلة.","conditions":"الشروط والمصادر والأذونات","record":"السجل والمراجع","code":"شيفرة JavaScript","cases":"حالات مرجعية","language":"اللغة","formula":"المعادلة الموثقة","edition":"إصدار الطريقة","limits":"الحدود والفئة السكانية","references":"المراجع"}},"zh":{"tool":{"id":"metodo-de-capurro","title":"Capurro 法（躯体指标）","titleLocale":"zh","summary":"新生儿胎龄","lead":"当产科孕周不明或存疑时，通过体格检查估计新生儿胎龄。","fields":[["pele","皮肤质地","sel",{"opts":{"0":"极薄，胶冻样","5":"薄且光滑","10":"稍厚，轻微表面脱屑","15":"厚，有浅表皱纹，手足脱屑","20":"厚、羊皮纸样，有深裂纹"},"unitLocale":"zh","displayLocale":"zh","optionLocales":{"0":"zh","5":"zh","10":"zh","15":"zh","20":"zh"}}],["orelha","耳廓形态","sel",{"opts":{"0":"扁平、形态不规则，耳廓未卷曲","8":"耳廓边缘部分卷曲","16":"耳廓整个上部部分卷曲","24":"耳廓完全卷曲"},"unitLocale":"zh","displayLocale":"zh","optionLocales":{"0":"zh","8":"zh","16":"zh","24":"zh"}}],["mama","乳腺大小","sel",{"opts":{"0":"不可触及","5":"可触及，小于5 mm","10":"5至10 mm","15":"大于10 mm"},"unitLocale":"zh","displayLocale":"zh","optionLocales":{"0":"zh","5":"zh","10":"zh","15":"zh"}}],["mamilo","乳头形成","sel",{"opts":{"0":"仅可见，无乳晕","5":"乳晕光滑、扁平，直径小于7.5 mm","10":"乳晕有点状纹理，边缘不隆起，直径大于7.5 mm","15":"乳晕有点状结构，边缘隆起，直径大于7.5 mm"},"unitLocale":"zh","displayLocale":"zh","optionLocales":{"0":"zh","5":"zh","10":"zh","15":"zh"}}],["pregas","足底纹","sel",{"opts":{"0":"无褶皱","5":"前半部纹理不清楚","10":"前半部纹理清楚，前三分之一有沟","15":"前半部有沟","20":"沟超过前半部"},"unitLocale":"zh","displayLocale":"zh","optionLocales":{"0":"zh","5":"zh","10":"zh","15":"zh","20":"zh"}}]],"formula":"<p><strong>胎龄（天）=204+总分</strong>，基于5项体征。除以7得周数。</p><p>Capurro还描述了体征-神经系统形式（常数200，含神经系统征象）；本计算器仅使用不依赖新生儿神经状态的体征形式。</p>","sources":[["Capurro H et al. A simplified method for diagnosis of gestational age in the newborn infant. J Pediatr, 1978.","https://doi.org/10.1016/S0022-3476(78)80621-0"],["Ministério da Saúde,AIDPI neonatal5ªedição,section5.1","https://bvsms.saude.gov.br/bvs/publicacoes/manual_AIDPI_neonatal_5ed.pdf"],["Ministério da Saúde,professional neonatal guidevol1","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_recem_nascido_%20guia_profissionais_saude_v1.pdf"],["Ministério da Saúde. Atenção à saúde do recém-nascido, v1, 2nd updated edition 2014, Quadro 11 PDF173 / printed172; official reproduction, not original1978 paper.","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_saude_recem_nascido_v1.pdf"]],"methodVersion":"Capurro 1978体征法5项：204+分数；非体征-神经系统法200+分数","methodVersionLocale":"zh","limits":"本工具实现的是体征型Capurro，使用五项身体体征和常数204，而非体征神经型变体。所查阅的巴西卫生部新生儿指导描述其适用于孕29周起的新生儿，尤其是月经日期不明时。不能假定它对低于该范围的极早产儿具有同样表现。各项体征必须通过适当的体格检查评估；因分娩体位暂时压平的耳廓不能当作成熟度的反映。 卫生部官方新生儿指南2014年第二次更新版的表11中，乳头形成10分选项描述直径大于7.5 mm、边缘不隆起。本次阅读的是官方转载版本，并非完整审查1978年的原始论文。修正标签保留代码及10分；不验证体格检查，也不解决图中未明确说明的相等边界。","limitsLocale":"zh","resultLabels":{"Idade gestacional pelo método de Capurro somático":"根据 Capurro 躯体法计算孕周","Método de Capurro (somático)":"Capurro 法（躯体指标）"},"resultUnits":{"de idade gestacional":"妊娠年龄"},"resultValues":{"29s 1d":"29 周 1 天","36s 5d":"36 周 5 天","37s 6d":"37 周 6 天","42s 4d":"42 周 4 天"}},"shared":{"select":"请选择","yes":"是","no":"否","optional":"选填","numeric":"数值","range":"范围","calculate":"计算","calculating":"计算中…","clear":"清除","heading":"透明计算","intro":"请核对适用人群、单位和版本。结果展示公式或分类，不自动作出治疗决定。","restricted":"可查阅工具记录","restrictedNote":"本版本暂停计算。清单、待审事项和来源仍公开。","resultNote":"公式或分类结果。解释、处理及适用性须结合专业评估和所选来源。","invalid":"无法使用这些数值计算。请核对使用条件。","unavailable":"计算服务暂不可用。请重试。","connection":"无法连接计算服务。请检查网络后重试。","check":"请检查输入值。","fleischner":"计算前：此参考适用于偶然发现的肺结节。建议不适用于35岁以下人群、肺癌筛查、免疫抑制或已知原发性癌症患者。","incompleteAssessment":"未完成评估，无法计算总分。"},"ui":{"brand":"ELUCENIA · 集成代码","clinical":"尚未开展独立临床审查。","conditions":"条件、来源与许可","record":"记录与参考文献","code":"JavaScript代码","cases":"参考案例","language":"语言","formula":"已记录的公式","edition":"方法版本","limits":"限制与适用人群","references":"参考文献"}},"ja":{"tool":{"id":"metodo-de-capurro","title":"Capurro法（身体所見）","titleLocale":"ja","summary":"新生児の在胎週数","lead":"産科での妊娠期間の推定が不明または不確かな場合、身体診察から新生児の在胎週数を推定します。","fields":[["pele","皮膚の質感","sel",{"opts":{"0":"非常に薄くゼラチン状","5":"薄く滑らか","10":"やや厚く，軽い表層落屑","15":"厚く，表面のしわ，手足の落屑","20":"厚く羊皮紙状で深い亀裂あり"},"unitLocale":"ja","displayLocale":"ja","optionLocales":{"0":"ja","5":"ja","10":"ja","15":"ja","20":"ja"}}],["orelha","耳介の形状","sel",{"opts":{"0":"平坦で形が不整，耳介の巻き込みなし","8":"耳介の縁が部分的に巻き込む","16":"耳介上部全体が部分的に巻き込む","24":"耳介が完全に巻き込む"},"unitLocale":"ja","displayLocale":"ja","optionLocales":{"0":"ja","8":"ja","16":"ja","24":"ja"}}],["mama","乳腺の大きさ","sel",{"opts":{"0":"触知不能","5":"触知可能，5 mm未満","10":"5～10 mm","15":"10 mm超"},"unitLocale":"ja","displayLocale":"ja","optionLocales":{"0":"ja","5":"ja","10":"ja","15":"ja"}}],["mamilo","乳頭の形成","sel",{"opts":{"0":"見えるのみ，乳輪なし","5":"乳輪が滑らかで平坦，直径7.5 mm未満","10":"点状の乳輪、縁は隆起せず、直径7.5 mmより大きい","15":"乳輪が点状，縁の隆起あり，直径7.5 mm超"},"unitLocale":"ja","displayLocale":"ja","optionLocales":{"0":"ja","5":"ja","10":"ja","15":"ja"}}],["pregas","足底皺襞","sel",{"opts":{"0":"しわなし","5":"前半分の線が不明瞭","10":"前半分の線が明瞭で，前方3分の1に溝","15":"前半分に溝","20":"前半分を超える範囲に溝"},"unitLocale":"ja","displayLocale":"ja","optionLocales":{"0":"ja","5":"ja","10":"ja","15":"ja","20":"ja"}}]],"formula":"<p><strong>在胎日数=204+合計点</strong>（5つの身体所見）。7で割ると週数になります。</p><p>Capurroは身体・神経所見を用いる方法（定数200、神経所見を含む）も記載しました。本計算は、新生児の神経学的状態に依存しない身体所見法のみを使います。</p>","sources":[["Capurro H et al. A simplified method for diagnosis of gestational age in the newborn infant. J Pediatr, 1978.","https://doi.org/10.1016/S0022-3476(78)80621-0"],["Ministério da Saúde,AIDPI neonatal5ªedição,section5.1","https://bvsms.saude.gov.br/bvs/publicacoes/manual_AIDPI_neonatal_5ed.pdf"],["Ministério da Saúde,professional neonatal guidevol1","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_recem_nascido_%20guia_profissionais_saude_v1.pdf"],["Ministério da Saúde. Atenção à saúde do recém-nascido, v1, 2nd updated edition 2014, Quadro 11 PDF173 / printed172; official reproduction, not original1978 paper.","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_saude_recem_nascido_v1.pdf"]],"methodVersion":"Capurro 1978身体所見5項目：204+点；身体・神経所見法200+点ではない","methodVersionLocale":"ja","limits":"このツールは、五つの身体所見と定数204を用いる身体所見型Capurroを実装し、身体・神経所見型ではありません。参照したブラジル保健省の新生児指針では、特に月経による妊娠日付が不明な場合、妊娠29週以降の新生児での使用を説明しています。この範囲未満の超早産児での性能を前提にしません。所見には適切な身体診察が必要です。分娩時の体位で一時的に平たくなった耳を、成熟度の所見として扱わないでください。 保健省の公式ガイド2014年更新第2版の表11では、乳頭形成の10点選択肢を直径7.5 mmより大きく、縁が隆起していないものと記載している。これは公式転載資料の確認であり、1978年の原著論文の全文レビューではない。ラベルの修正ではコードと10点を保持する。身体診察を検証せず、図で明示されない等号の境界も確定しない。","limitsLocale":"ja","resultLabels":{"Idade gestacional pelo método de Capurro somático":"身体所見によるCapurro法の妊娠週数","Método de Capurro (somático)":"Capurro法（身体所見）"},"resultUnits":{"de idade gestacional":"妊娠週数"},"resultValues":{"29s 1d":"29週1日","36s 5d":"36週5日","37s 6d":"37週6日","42s 4d":"42週4日"}},"shared":{"select":"選択","yes":"はい","no":"いいえ","optional":"任意","numeric":"数値","range":"範囲","calculate":"計算","calculating":"計算中…","clear":"クリア","heading":"根拠を明示して計算","intro":"対象集団、単位、版を確認してください。結果は式または分類を示すもので、治療方針を自動決定しません。","restricted":"記録を参照できます","restrictedNote":"この版では計算を停止しています。目録、未完了の審査、出典は公開されています。","resultNote":"式または分類の結果です。解釈、対応、適用可能性は専門家による評価と選択した出典に依存します。","invalid":"この値では計算できません。使用条件を確認してください。","unavailable":"計算サービスを利用できません。再試行してください。","connection":"計算サービスに接続できません。接続を確認して再試行してください。","check":"入力値を確認してください。","fleischner":"計算前：偶発的に発見された肺結節に関する参考です。35歳未満、肺がん検診、免疫抑制、既知の原発がんには推奨を適用できません。","incompleteAssessment":"評価が完了していないため合計を計算できません。"},"ui":{"brand":"ELUCENIA · 連携コード","clinical":"独立した臨床レビューは実施されていません。","conditions":"条件・出典・許諾","record":"記録・参考文献","code":"JavaScriptコード","cases":"参照ケース","language":"言語","formula":"記載された計算式","edition":"方法の版","limits":"限界・対象集団","references":"参考文献"}},"hi":{"tool":{"id":"metodo-de-capurro","title":"Capurro विधि (शारीरिक)","titleLocale":"hi","summary":"नवजात की गर्भकालीन आयु","lead":"प्रसूति काल निर्धारण अज्ञात या संदिग्ध होने पर शारीरिक परीक्षण से नवजात की गर्भकालीन आयु का अनुमान लगाता है।","fields":[["pele","त्वचा की बनावट","sel",{"opts":{"0":"बहुत पतली, जिलेटिन जैसी","5":"पतली और चिकनी","10":"कुछ मोटी, हल्की सतही पपड़ी","15":"मोटी, सतही झुर्रियाँ, हाथों और पैरों पर पपड़ी","20":"मोटी, चर्मपत्र जैसी, गहरी दरारों के साथ"},"unitLocale":"hi","displayLocale":"hi","optionLocales":{"0":"hi","5":"hi","10":"hi","15":"hi","20":"hi"}}],["orelha","कान का आकार","sel",{"opts":{"0":"चपटी, अनियमित आकार, कान का बाहरी भाग मुड़ा नहीं","8":"कान के बाहरी भाग का किनारा आंशिक रूप से मुड़ा","16":"कान के पूरे ऊपरी भाग में आंशिक मोड़","24":"कान का बाहरी भाग पूरी तरह मुड़ा"},"unitLocale":"hi","displayLocale":"hi","optionLocales":{"0":"hi","8":"hi","16":"hi","24":"hi"}}],["mama","स्तन ग्रंथि का आकार","sel",{"opts":{"0":"स्पर्श से महसूस नहीं होता","5":"स्पर्श से महसूस होता, 5 mm से कम","10":"5 और 10 mm के बीच","15":"10 mm से अधिक"},"unitLocale":"hi","displayLocale":"hi","optionLocales":{"0":"hi","5":"hi","10":"hi","15":"hi"}}],["mamilo","निप्पल का विकास","sel",{"opts":{"0":"केवल दिखता है, एरिओला नहीं","5":"चिकनी और चपटी एरिओला, व्यास 7.5 mm से कम","10":"बिंदुदार स्तनमंडल, किनारा उभरा नहीं है, व्यास 7.5 mm से अधिक","15":"बिंदुयुक्त एरिओला, उठा हुआ किनारा, व्यास 7.5 mm से अधिक"},"unitLocale":"hi","displayLocale":"hi","optionLocales":{"0":"hi","5":"hi","10":"hi","15":"hi"}}],["pregas","तलवे की सिलवटें","sel",{"opts":{"0":"सिलवटें नहीं","5":"अग्र आधे में अस्पष्ट चिह्न","10":"अग्र आधे में स्पष्ट चिह्न और अग्र एक-तिहाई में खाँचे","15":"अग्र आधे में खाँचे","20":"अग्र आधे से अधिक भाग में खाँचे"},"unitLocale":"hi","displayLocale":"hi","optionLocales":{"0":"hi","5":"hi","10":"hi","15":"hi","20":"hi"}}]],"formula":"<p><strong>गर्भकालीन आयु (दिन) = 204 + अंकों का योग</strong>, 5 शारीरिक संकेतों के लिए। सप्ताह पाने हेतु 7 से भाग दें।</p><p>Capurro ने शारीरिक-न्यूरोलॉजिकल रूप भी बताया (स्थिरांक 200, न्यूरोलॉजिकल संकेत सहित); यह कैलकुलेटर केवल शारीरिक रूप लेता है, जो नवजात की न्यूरोलॉजिकल स्थिति पर निर्भर नहीं है।</p>","sources":[["Capurro H et al. A simplified method for diagnosis of gestational age in the newborn infant. J Pediatr, 1978.","https://doi.org/10.1016/S0022-3476(78)80621-0"],["Ministério da Saúde,AIDPI neonatal5ªedição,section5.1","https://bvsms.saude.gov.br/bvs/publicacoes/manual_AIDPI_neonatal_5ed.pdf"],["Ministério da Saúde,professional neonatal guidevol1","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_recem_nascido_%20guia_profissionais_saude_v1.pdf"],["Ministério da Saúde. Atenção à saúde do recém-nascido, v1, 2nd updated edition 2014, Quadro 11 PDF173 / printed172; official reproduction, not original1978 paper.","https://bvsms.saude.gov.br/bvs/publicacoes/atencao_saude_recem_nascido_v1.pdf"]],"methodVersion":"Capurro 1978 शारीरिक 5 संकेत: 204+अंक; शारीरिक-न्यूरोलॉजिकल रूप 200+अंक नहीं","methodVersionLocale":"hi","limits":"यह उपकरण पाँच शारीरिक संकेतों और स्थिरांक 204 वाला सोमैटिक Capurro लागू करता है, सोमैटोन्यूरोलॉजिकल प्रकार नहीं। परामर्शित ब्राज़ील स्वास्थ्य मंत्रालय का नवजात मार्गदर्शन 29 सप्ताह से जन्मे नवजातों में इसका उपयोग बताता है, विशेषकर जब मासिक धर्म आधारित तिथि ज्ञात न हो। इस सीमा से नीचे के अत्यंत समयपूर्व शिशुओं में वही प्रदर्शन नहीं माना जाता। संकेतों के लिए उचित शारीरिक परीक्षण चाहिए; जन्म की स्थिति से अस्थायी रूप से चपटा हुआ कान परिपक्वता का संकेत नहीं माना जाना चाहिए। स्वास्थ्य मंत्रालय की आधिकारिक मार्गदर्शिका के 2014 के दूसरे अद्यतन संस्करण की तालिका 11 में, स्तनाग्र के गठन वाले 10-अंक के विकल्प में 7.5 mm से अधिक व्यास और बिना उभरा किनारा वर्णित है। यह आधिकारिक पुनर्प्रस्तुति का पठन है, 1978 के मूल लेख की पूरी समीक्षा नहीं। लेबल का सुधार कोड और 10 अंक सुरक्षित रखता है; इससे शारीरिक परीक्षण प्रमाणित नहीं होता और चित्र में अस्पष्ट समानता की सीमाएँ तय नहीं होतीं।","limitsLocale":"hi","resultLabels":{"Idade gestacional pelo método de Capurro somático":"Capurro शारीरिक विधि से गर्भावधि","Método de Capurro (somático)":"Capurro विधि (शारीरिक)"},"resultUnits":{"de idade gestacional":"गर्भावधि का"},"resultValues":{"29s 1d":"29 सप्ताह 1 दिन","36s 5d":"36 सप्ताह 5 दिन","37s 6d":"37 सप्ताह 6 दिन","42s 4d":"42 सप्ताह 4 दिन"}},"shared":{"select":"चुनें","yes":"हाँ","no":"नहीं","optional":"वैकल्पिक","numeric":"संख्यात्मक मान","range":"सीमा","calculate":"गणना करें","calculating":"गणना जारी है…","clear":"साफ़ करें","heading":"पारदर्शिता के साथ गणना","intro":"जनसमूह, इकाइयाँ और संस्करण जाँचें। परिणाम सूत्र या वर्गीकरण दिखाता है; यह स्वतः उपचार संबंधी निर्णय नहीं देता।","restricted":"रिकॉर्ड देखने के लिए उपलब्ध है","restrictedNote":"इस संस्करण में गणना रुकी हुई है। सूची, लंबित समीक्षा और स्रोत सार्वजनिक हैं।","resultNote":"सूत्र या वर्गीकरण का परिणाम। व्याख्या, कार्यवाही और उपयुक्तता पेशेवर मूल्यांकन और चुने गए स्रोत पर निर्भर है।","invalid":"इन मानों से गणना नहीं हो सकी। उपयोग की शर्तें जाँचें।","unavailable":"गणना सेवा उपलब्ध नहीं है। फिर प्रयास करें।","connection":"गणना सेवा से संपर्क नहीं हो सका। कनेक्शन जाँचकर फिर प्रयास करें।","check":"दर्ज मान जाँचें।","fleischner":"गणना से पहले: आकस्मिक रूप से पाए गए फेफड़ों के नोड्यूल के लिए संदर्भ। सिफ़ारिशें 35 वर्ष से कम आयु, फेफड़ों के कैंसर की स्क्रीनिंग, प्रतिरक्षा दमन या ज्ञात प्राथमिक कैंसर पर लागू नहीं होतीं।","incompleteAssessment":"पूर्ण मूल्यांकन के बिना कुल स्कोर नहीं निकाला जा सकता।"},"ui":{"brand":"ELUCENIA · एकीकरण कोड","clinical":"स्वतंत्र नैदानिक समीक्षा नहीं की गई है।","conditions":"शर्तें, स्रोत और अनुमतियाँ","record":"रिकॉर्ड और संदर्भ","code":"JavaScript कोड","cases":"संदर्भ मामले","language":"भाषा","formula":"दस्तावेज़ित सूत्र","edition":"विधि का संस्करण","limits":"सीमाएँ और जनसमूह","references":"संदर्भ"}}}};
